"""Pydantic contracts shared across the API, orchestrators, and the LLM layer.

These double as the `response_model` passed to `instructor`, so the LLM's structured
output is validated at the boundary -- a malformed/hallucinated shape fails fast
instead of silently reaching the client.
"""

from datetime import UTC, datetime
from enum import StrEnum
from typing import Literal

from pydantic import BaseModel, Field

NOT_LEGAL_ADVICE_DISCLAIMER = (
    "This analysis is generated by an AI system for informational purposes only and does "
    "not constitute legal advice. It is not a substitute for review by a licensed attorney. "
    "For decisions with material financial or legal consequences, consult a lawyer."
)


class Severity(StrEnum):
    RED = "red"
    YELLOW = "yellow"
    GREEN = "green"


class RiskProfile(BaseModel):
    """User-supplied context that personalizes the analysis (Node/Postgres owns the durable copy)."""

    role: str = Field(default="freelancer", description="e.g. freelance developer, creator, founder")
    risk_tolerance: Literal["conservative", "balanced", "aggressive"] = "balanced"
    priorities: list[str] = Field(
        default_factory=list,
        description="e.g. ['retain IP ownership', 'avoid non-competes', 'fast payment terms']",
    )


class SourceSpan(BaseModel):
    """Character offsets into the parsed document markdown, used for UI highlighting."""

    start: int
    end: int


class ClauseFindingDraft(BaseModel):
    """What the LLM is actually asked to produce (`instructor` response_model).

    Deliberately excludes `source_span`: LLMs cannot reliably count characters, and
    asking for exact offsets causes tool-call validation failures or hallucinated
    (e.g. `[-1, -1]`) values in practice. Instead the model quotes the clause
    verbatim, and we locate the real offsets deterministically afterwards (see
    `pipeline/grounding.py`).
    """

    category: str = Field(
        description="Short uppercase clause category, e.g. IP_ASSIGNMENT, ARBITRATION, "
        "NON_COMPETE, INDEMNIFICATION, PAYMENT_TERMS, TERMINATION, LIABILITY_CAP"
    )
    severity: Severity
    title: str = Field(description="Short human-readable finding title")
    explanation: str = Field(description="Plain-English explanation of the risk, no legal jargon")
    market_comparison: str = Field(
        description="How this clause compares to the retrieved market-standard clause(s)"
    )
    suggested_redline: str = Field(
        default="", description="Concrete suggested replacement/negotiation language, if applicable"
    )
    quoted_text: str = Field(
        description="The exact clause text this finding refers to, copied VERBATIM "
        "(word-for-word, same punctuation/casing) from the CONTRACT TEXT. Do not "
        "paraphrase or summarize -- it must be an exact substring of the contract."
    )
    confidence: float = Field(ge=0.0, le=1.0)


class RiskReportDraft(BaseModel):
    """Raw `instructor` response_model for the analysis call; see `ClauseFindingDraft`."""

    safety_score: int = Field(ge=1, le=100, description="Overall contract safety score, 1-100")
    summary: str = Field(description="2-4 sentence plain-English summary of overall risk")
    findings: list[ClauseFindingDraft] = Field(default_factory=list)


class ClauseFinding(BaseModel):
    category: str = Field(
        description="Short uppercase clause category, e.g. IP_ASSIGNMENT, ARBITRATION, "
        "NON_COMPETE, INDEMNIFICATION, PAYMENT_TERMS, TERMINATION, LIABILITY_CAP"
    )
    severity: Severity
    title: str = Field(description="Short human-readable finding title")
    explanation: str = Field(description="Plain-English explanation of the risk, no legal jargon")
    market_comparison: str = Field(
        description="How this clause compares to the retrieved market-standard clause(s)"
    )
    suggested_redline: str = Field(
        default="", description="Concrete suggested replacement/negotiation language, if applicable"
    )
    quoted_text: str = Field(default="", description="Verbatim clause excerpt this finding refers to")
    source_span: SourceSpan | None = Field(
        default=None,
        description="Where in the document this clause appears, resolved by exact/fuzzy "
        "string search of `quoted_text` -- null if it could not be located",
    )
    confidence: float = Field(ge=0.0, le=1.0)


class SafetyScoreOnly(BaseModel):
    """Reduced-cost output for the free 'Risk Scanner' PLG flow: a score + teaser
    summary only, no clause-level redlines (those are gated behind the paid analysis)."""

    safety_score: int = Field(ge=1, le=100)
    summary: str = Field(description="1-2 sentence teaser summary, no specifics that give away findings")
    risk_area_count: int = Field(ge=0, description="Count of atypical-risk areas found, without detail")
    disclaimer: str = NOT_LEGAL_ADVICE_DISCLAIMER


class RiskReport(BaseModel):
    safety_score: int = Field(ge=1, le=100, description="Overall contract safety score, 1-100")
    summary: str = Field(description="2-4 sentence plain-English summary of overall risk")
    findings: list[ClauseFinding] = Field(default_factory=list)
    disclaimer: str = NOT_LEGAL_ADVICE_DISCLAIMER


class Citation(BaseModel):
    chunk_id: str
    source: Literal["document", "standard_corpus"]
    span: SourceSpan | None = None
    excerpt: str = ""


class ChatTurn(BaseModel):
    role: Literal["user", "assistant"]
    content: str
    citations: list[Citation] = Field(default_factory=list)
    created_at: datetime = Field(default_factory=lambda: datetime.now(UTC))


class RetrievedChunk(BaseModel):
    """A single chunk returned from hybrid retrieval, already reranked."""

    chunk_id: str
    text: str
    source: Literal["document", "standard_corpus"]
    category: str | None = None
    clause_type: str | None = None
    span: SourceSpan | None = None
    score: float = 0.0


class JobStatus(StrEnum):
    QUEUED = "queued"
    PROCESSING = "processing"
    COMPLETE = "complete"
    FAILED = "failed"


class AnalyzeJobResult(BaseModel):
    job_id: str
    document_id: str
    status: JobStatus
    report: RiskReport | None = None
    error: str | None = None
